import type { TaskHandler } from '@teambit/builder';
import {
  LinterTask,
  type LinterTaskOptions,
} from '@teambit/defender.linter-task';
import { OxlintLinter } from './oxlint-linter.js';
import type { OxlintOptions } from './oxlint-linter-options.js';

export type OxlintTaskOptions = OxlintOptions &
  Pick<LinterTaskOptions, 'description'>;

/** @deprecated use OxlintTaskOptions */
export type OXlintTaskOptions = OxlintTaskOptions;

/**
 * Run Oxlint as part of a component build pipeline.
 */
export const OxlintTask = {
  from: (options: OxlintTaskOptions): TaskHandler => {
    const name = options.name || 'OxlintLint';
    const description = options.description || 'linting components using Oxlint';
    return LinterTask.from({
      ...options,
      name,
      description,
      linter: OxlintLinter.from(options),
    });
  },
};
